    public static function svg(string $name, string $class = ''): string
    {
        $path = static::$paths[$name] ?? '';
        if ($path === '') {
            return '';
        }

        return '<svg class="i ' . $class . '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' . $path . '</svg>';
    }
